		onLog = false;
	}

	function run() {
		this.update();
		this.show();
	}

	function show() {
		frog(pos.x, pos.y, radians(dir), size);
	}

	function update() {
		if (!onLog) {
			targetPos.x = (targetPos.x - (targetPos.x % 55)) + (width % 55) / 2;
		}

		onLog = false;

		if (gameStatus == "Playing") {

