				high = ((height - targetPos.y) - 55 / 2) / 55;
				setCookie("high", high);
			}

			for (i = 0; i < plains.length; i++) {
				for (n = 0; n < plains[i].lanes.length; n++) {
					for (j = 0; j < plains[i].lanes[n].length; j++) {
