							targetPos.x += plains[i].lanes[n][j].speed;
							pos.x += plains[i].lanes[n][j].speed;
							onLog = true;
						}

						if (plains[i].lanes[n][j] && plains[i].lanes[n][j].mode == "COINS" && targetPos.x > plains[i].lanes[n][j].pos.x - (plains[i].lanes[n][j].w2 / 2) && targetPos.x < plains[i].lanes[n][j].pos.x + (plains[i].lanes[n][j].w2 / 2) && targetPos.y > plains[i].lanes[n][j].pos.y - 30 && targetPos.y < plains[i].lanes[n][j].pos.y + 30) {
							coins++;
