class Selector {
	let pos;
	let vel;
	string title;
	string mode;
	string status;
	let targetPos;
	let h;
	let speed;
	let delay;
	let frames;
	let number;

	constructor(_pos, _title, _mode, _speed, _status, _number) {
		pos = _pos;
		vel = new PVector();
		targetPos = new PVector(width / 2, _pos.y);;
		title = _title;
		mode = _mode;
		if (mode !== "Title") {
			h = 50;
		} else {
			h = 150;
		}
		delay = 0;
		frames = 0;
		speed = _speed;
		status = _status;
		number = _number;
	}

	function run() {
		this.update();
		this.show();
	}

	function update() {
		pos.add(vel);
		frames++;
		pos.y += sin((frameCount / 25) + number / 2);
		if (frames > delay) {
			if (status == "in") {
				pos = new PVector(lerp(pos.x, targetPos.x, speed), lerp(pos.y, targetPos.y, speed));
				vel.mult(0);
			} else if (status == "out") {
				vel.x -= speed * 20;
			}
		}

		if (pos.x < -width / 2 && status == "out") {
			status = "Waiting";
			vel.mult(0);
			pos.x = width + width / 2 + 50;
		}

		if (status == "Waiting") {
			vel.mult(0);
			pos.x = width + width / 2 + 50;
		}
	}

	function show() {
		rectMode(CENTER);
		colorMode(HSB, 255, 255, 255, 255);
		fill(((number) * 255) / 40, 200, 255, 250);
		if (this.isTouched()) {
			fill(((number - 1) * 255) / 40, 200, 255, 200);
		}
		trapizoid(pos.x, pos.y, width, h);
		colorMode(RGB, 255, 255, 255, 255);
		fill(255);
		textAlign(CENTER, CENTER);
		textSize(h / 1.25);
		text(title, pos.x, pos.y);
		rectMode(CORNER);
	}

	function slideIn(_delay) {
		status = "let in";
		delay = _delay;
		frames = 0;
	}

	function slideOut(_delay) {
		status = "let out";
		delay = _delay;
		frames = 0;
	}

	fucntion isTouched() {
		return mode == "Selector" && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > pos.x - (width / 2) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < pos.x + (width / 2) && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > pos.y - (h / 2) && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < pos.y + (h / 2);
	}
}

function trapizoid(x, y, w, h) {
	pushMatrix();
	translate(x, y);
	beginShape();
	vertex(-w / 2, h / 2);
	vertex(-w / 2 - 50, -h / 2);
	vertex(w / 2, -h / 2);
	vertex(w / 2 + 50, h / 2);
	//vertex(-w / 2, h / 2);
	endShape(CLOSE);
	popMatrix();
}

